class Base {
public:
    // CRITICAL: Required for correct cleanup of polymorphic arrays.
    virtual ~Base() = default;
};

class Derived : public Base {
    int* resource = new int[5];
public:
    ~Derived() override { delete[] resource; }
};

// Allocation of a polymorphic array
Base* base_array = new Derived[3];

// Deletion must use the virtual mechanism to invoke
// ~Derived() for all elements.
delete[] base_array;
// If ~Base() is not virtual, only Base destructors run.
// (Undefined Behavior/Resource Leak)
